import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  const ownedMaterials = [];
  const ownedGeometries = [];
  const ownedTextures = [];
  const timelines = [];
  const primitiveResults = [];

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = {
    ink: visualSpec.colors?.ink ?? '#16161d',
    paper: visualSpec.colors?.paper ?? '#e8ecf2',
    accent: visualSpec.colors?.accent ?? '#ff2a38',
    surface: visualSpec.colors?.surface ?? '#0b0b10'
  };

  const makeGradientMaterial = (bottom, top) => {
    const material = new MeshBasicNodeMaterial();
    const gradient = mix(
      vec3(bottom[0], bottom[1], bottom[2]),
      vec3(top[0], top[1], top[2]),
      smoothstep(0.0, 1.0, uv().y)
    );
    material.colorNode = gradient;
    ownedMaterials.push(material);
    return material;
  };

  const backdropGeometry = new PlaneGeometry(7.0, 6.0);
  ownedGeometries.push(backdropGeometry);
  const backdropMaterial = makeGradientMaterial(
    [0.043, 0.043, 0.063],
    [0.086, 0.086, 0.114]
  );
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  const panelGeometry = new PlaneGeometry(5.8, 3.35);
  ownedGeometries.push(panelGeometry);
  const panelMaterial = makeGradientMaterial(
    [0.043, 0.043, 0.063],
    [0.086, 0.086, 0.114]
  );
  const panel = new Mesh(panelGeometry, panelMaterial);
  panel.position.set(0, 0, 0);
  root.add(panel);

  const borderGeometry = new PlaneGeometry(5.84, 0.025);
  ownedGeometries.push(borderGeometry);
  const borderMaterial = new MeshBasicNodeMaterial({ color: colors.accent });
  ownedMaterials.push(borderMaterial);

  const topBorder = new Mesh(borderGeometry, borderMaterial);
  topBorder.position.set(0, 1.575, 0.035);
  root.add(topBorder);

  const accentGeometry = new PlaneGeometry(0.72, 0.045);
  ownedGeometries.push(accentGeometry);
  const accentMaterial = new MeshBasicNodeMaterial({ color: colors.accent });
  ownedMaterials.push(accentMaterial);

  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.position.set(-2.35, -1.22, 0.045);
  root.add(accent);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const content = typeof item.text === 'string' ? item.text : '';
    if (!content) continue;

    const textObject = ctx.fontAtlas.createText(content, {
      fontSize: item.typography?.fontSize ?? 39,
      color: colors.paper,
      align: 'left'
    });

    textObject.position.set(-2.35, 0.05, 0.08);
    root.add(textObject);
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((loadedTexture) => {
      if (!loadedTexture || root.userData.cleaned) return;

      ownedTextures.push(loadedTexture);
      const grainNode = texture(loadedTexture);
      const gradient = mix(
        vec3(0.043, 0.043, 0.063),
        vec3(0.086, 0.086, 0.114),
        smoothstep(0.0, 1.0, uv().y)
      );

      panelMaterial.colorNode = gradient.mul(grainNode.rgb);
      panelMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  root.scale.set(0.98, 0.98, 0.98);
  const entrance = gsap.timeline();
  entrance
    .to(root.position, {
      y: '+=0.22',
      duration: 0.01,
      ease: 'power3.out'
    })
    .to(root.position, {
      y: '-=0.22',
      duration: 0.7,
      ease: 'power3.out'
    })
    .to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out'
    }, '<');
  timelines.push(entrance);

  for (const primitive of config.cinematicPrimitives ?? []) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler === 'function') {
      const result = handler(root, primitive.params);
      if (result) primitiveResults.push(result);
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (root.userData.cleaned) return;
    root.userData.cleaned = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const result of primitiveResults) {
      result?.cleanup?.();
      result?.timeline?.kill?.();
    }

    for (const textureResource of ownedTextures) {
      textureResource?.dispose?.();
    }

    for (const material of ownedMaterials) {
      material?.dispose?.();
    }

    for (const geometry of ownedGeometries) {
      geometry?.dispose?.();
    }
  };

  return root;
}
